function expandedLesson(input: Omit<Lesson, "pages"> & { idea: string; discover: string; practice: string }) {
  return lesson({
    ...input,
    pages: [
      { heading: "نكتشف الفكرة", body: input.idea },
      { heading: "نلاحظ ونجرب", body: input.discover },
      { heading: "نطبق بهدوء", body: input.practice, note: "تذكر: السؤال وإعادة المحاولة جزءان مهمان من التعلم." },
    ],
  });
}

