export const seedLessons: Lesson[] = [...primaryLessons, ...supplementalLessons];

export function getLesson(id: string | string[] | undefined) {
  const normalized = Array.isArray(id) ? id[0] : id;
  return seedLessons.find((item) => item.id === normalized) ?? seedLessons[0];
}

export const subjectFilters = ["الكل", "إسلامي", "مدرسي", "مستقبل", "حياة"] as const;

export function matchesFilter(item: Lesson, filter: (typeof subjectFilters)[number]) {
  if (filter === "الكل") return true;
  if (filter === "إسلامي") return ["القرآن", "الحديث النبوي", "السيرة النبوية", "قصص الأنبياء", "العبادات", "الأذكار والأدعية", "المواسم الإسلامية"].includes(item.subject);
  if (filter === "مدرسي") return ["الرياضيات", "العلوم", "اللغة العربية", "اللغة الإنجليزية", "الثقافة العامة"].includes(item.subject);
  if (filter === "مستقبل") return ["البرمجة", "الذكاء الاصطناعي", "الأمان الرقمي", "المهارات الرقمية"].includes(item.subject);
  return ["المهارات الحياتية", "الأخلاق", "القصص", "الألعاب التعليمية", "المشاريع"].includes(item.subject);
}
